  // report timeouts, ignore user cancellations
}
```
How can the `catch` block tell the two cases apart?

`fetchJson()` returns a promise that rejects. What does `getData()` produce?

```js
async function getData() {
  try {
    return fetchJson();
  } catch (e) {
    return 'fallback';
  }
}
```

Which statement about this concurrency-limited map is correct?

```js
async function mapLimit(items, limit, fn) {
  const results = [];
  let i = 0;
  async function worker() {
    while (i < items.length) {
      const idx = i++;
      results[idx] = await fn(items[idx]);
    }
  }
  await Promise.all(Array.from({ length: limit }, worker));
  return results;
}
```

A helper should retry a flaky request up to 3 times, and it is called as `retry(fetchReport(), 3)`. Why doesn't it ever succeed after the first failure?

```js
async function retry(promise, attempts) {
  try {
    return await promise;
  } catch (e) {
    if (attempts <= 1) throw e;
    return retry(promise, attempts - 1);
  }
}
```

